CHANNELS_PER_UNIVERSE = 510
PIXELS_PER_UNIVERSE = 170
UNIVERSE_COUNT = 10

def _config(key, default):
    table = op('/project1/esp_artnet_live_config')
    for row in range(1, table.numRows):
        if table[row, 0].val == key:
            return table[row, 1].val
    return default

def _clamp01(value):
    return max(0.0, min(1.0, float(value)))

def onSetupParameters(scriptOp):
    return

def onPulse(par):
    return

def onCook(scriptOp):
    source = scriptOp.inputs[0] if scriptOp.inputs else None
    enabled = _config('enabled', '1') == '1'
    master = max(0.0, min(1.0, float(_config('master_brightness', '0.02'))))
    source_offset = max(0, int(_config('source_offset', '0')))
    pixel_count = max(0, min(1679, int(_config('pixel_count', '1679'))))
    order = _config('color_order', 'RGB').upper()
    if sorted(order) != ['B', 'G', 'R']:
        order = 'RGB'

    scriptOp.clear()
    scriptOp.numSamples = CHANNELS_PER_UNIVERSE
    outputs = [scriptOp.appendChan('Universe%d' % u) for u in range(UNIVERSE_COUNT)]

    if not enabled or source is None:
        return

    sources = {'R': source['r'], 'G': source['g'], 'B': source['b']}
    for pixel in range(pixel_count):
        source_index = source_offset + pixel
        if source_index >= source.numSamples:
            break
        universe = pixel // PIXELS_PER_UNIVERSE
        local_pixel = pixel % PIXELS_PER_UNIVERSE
        channel_index = local_pixel * 3
        output = outputs[universe]
        for component, key in enumerate(order):
            output[channel_index + component] = round(_clamp01(sources[key][source_index]) * 255.0 * master)

    # Unwritten channels are zero. In Universe 9, channels 447..509
    # therefore remain black after pixel 1678.
    return
